import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse(`{"title":"Device connector: what's actually left after alarms drop out","description":"","frontmatter":{"id":9,"title":"Device connector: what's actually left after alarms drop out","status":"decided","date":"August 2026","author":"Claude Code (session with the developer)","scope":"mobile","summary":"Candidate connector — originally proposed as flashlight control plus alarm set/clear","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/research/0009-device-connector.md"},"headers":[],"relativePath":"sovereign-edge/research/0009-device-connector.md","filePath":"sovereign-edge/research/0009-device-connector.md"}`),n={name:"sovereign-edge/research/0009-device-connector.md"};function s(r,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="research-0009-—-device-connector-what-s-actually-left-after-alarms-drop-out" tabindex="-1">Research 0009 — Device connector: what&#39;s actually left after alarms drop out <a class="header-anchor" href="#research-0009-—-device-connector-what-s-actually-left-after-alarms-drop-out" aria-label="Permalink to &quot;Research 0009 — Device connector: what&#39;s actually left after alarms drop out&quot;">​</a></h1><p><strong>Related:</strong> <a href="./../epics/mobile/connector-framework.html">Connector Framework</a>, <a href="./0005-calendar-connector.html">research 0005</a> (same Tier 3 classification and shared scaffolding prerequisite)</p><hr><h2 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to &quot;Question&quot;">​</a></h2><p>The original proposal paired flashlight control with &quot;set alarms, clear all the alarms.&quot; Is alarm management actually buildable on either platform, and if not, what does &quot;Device connector&quot; become?</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><ul><li><strong>Flashlight/torch is confirmed viable on both platforms.</strong> iOS <code>AVCaptureDevice.torchMode</code>, Android <code>CameraManager.setTorchMode()</code> — exposed via <code>expo-camera</code>&#39;s <code>CameraView</code> <code>enableTorch</code> prop. Requires the standard camera permission on both platforms even though nothing is captured — a normal, low-sensitivity ask, not a special/sensitive permission tier.</li><li><strong>Alarms — checked against each platform&#39;s actual public API surface:</strong><ul><li>iOS has no public API for third-party apps to create, list, or delete Clock alarms. Shortcuts/Siri App Intents integration exposes <em>this app&#39;s own</em> actions to Shortcuts, in the other direction — it does not grant control over the system Clock app.</li><li>Android&#39;s <code>AlarmClock</code> intents (<code>ACTION_SET_ALARM</code>, <code>ACTION_SET_TIMER</code>, <code>ACTION_SHOW_ALARMS</code>) let an app <strong>request</strong> that some clock app create an alarm, via an implicit intent the receiving app may or may not honor silently — and there is no public intent to <strong>enumerate or delete</strong> existing alarms. Any installed clock app can register as the handler, so even alarm creation isn&#39;t guaranteed to land in a specific app.</li><li>Net: alarm creation is possible only as a <strong>hand-off to whatever clock app is installed</strong> on Android — not a direct, silent action, and not guaranteed which app receives it — and isn&#39;t possible at all on iOS. &quot;Clear all the alarms&quot; is not achievable as a programmatic action on either platform via any public API found.</li></ul></li><li>With alarms out, &quot;Device connector&quot; as originally scoped is really just &quot;flashlight.&quot; A single-capability connector is thin enough to question whether it deserves its own manifest entry at all, versus being folded into something with a bit more surface.</li><li><strong>Brightness</strong> (<code>expo-brightness</code>) is a similarly simple on-device toggle worth pairing with flashlight: read/set screen brightness on both platforms. One wrinkle — Android&#39;s <em>system-wide</em> brightness write needs the <code>WRITE_SETTINGS</code> permission, a special permission granted via a system settings screen rather than a normal runtime dialog, unlike app-window-only brightness which needs nothing special. Scoping to app-window brightness avoids that heavier permission path unless system-wide control is specifically the goal.</li><li><strong>Resolved, per <a href="./0005-calendar-connector.html">0005</a>&#39;s reading of the actual implementation:</strong> this is a Tier 3 connector, same as Calendar. Tier 1&#39;s manifest schema hard-requires an HTTP <code>origin</code> and network permissions; there&#39;s no way to express &quot;call <code>expo-camera</code>&#39;s torch toggle&quot; in that shape, and the runtime&#39;s <code>executeConnectorCall()</code> has only ever implemented <code>case 1</code>. Tier 3 (&quot;first-party native OS integration&quot;) is named in research 0001 and reserved as an extension point in <code>executeConnectorCall()</code>&#39;s own doc comment, but not yet built. The permission <em>state machine</em> in <code>grants.ts</code> is already generic; only the <em>scope</em> it tracks (<code>grantedOrigins</code>, Tier-1-specific) needs a generalized equivalent for a capability-based scope like &quot;torch&quot; or &quot;brightness.&quot;</li></ul><h2 id="options-considered" tabindex="-1">Options considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options considered&quot;">​</a></h2><p><strong>A. Ship &quot;Device connector&quot; as flashlight-only, alarms dropped entirely.</strong></p><p><strong>B. Bundle flashlight + app-window brightness into one small &quot;Device Utilities&quot; connector, alarms dropped.</strong></p><p><strong>C. Keep researching whether any alarm capability is salvageable — e.g. accepting Android&#39;s hand-off-only, best-effort behavior, with no promise of deletion.</strong></p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p>Option B. Flashlight alone is a thin justification for a standalone connector; pairing it with app-window brightness (same &quot;simple on-device toggle&quot; shape, same low permission bar when scoped this way) gives it enough surface to be a coherent connector rather than a single-purpose one. Alarms dropped — option C stays available if a specific product reason to want partial, best-effort alarm creation shows up later, but nothing found here argues for taking on that asymmetry now.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h2><ul><li><strong>This is a Tier 3 connector</strong>, same classification as Calendar (<a href="./0005-calendar-connector.html">0005</a>) and Health/step-count (<a href="./0008-health-step-count.html">0008</a>). It shares the same unbuilt prerequisite (manifest schema variant, generalized grant scope, <code>case 3</code> runtime dispatch) — not a separate piece of work per connector.</li><li>Scope: flashlight (<code>device.set_torch</code>) + app-window brightness (<code>device.set_brightness</code>), not system-wide brightness.</li><li>Alarm management (create/list/clear) is dropped from scope — not a platform-parity gap to close later, but a capability that doesn&#39;t meaningfully exist to build against.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Is app-window-only brightness sufficient, or does the actual want extend to system-wide brightness (which pulls in Android&#39;s <code>WRITE_SETTINGS</code> special-permission flow)?</li><li>Does a two-capability &quot;Device Utilities&quot; connector want more capabilities before shipping, or is flashlight + brightness enough for a first version?</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><strong>Done:</strong> this connector has its own epic: <a href="./../epics/mobile/device-connector.html">device-connector.md</a> (task 11.1), slotted into <a href="./../../ROADMAP.html">ROADMAP.md</a> at 0.2.3 — right after Calendar.</p><p><strong>Actual next step for whoever picks this up:</strong> same blocker as Calendar — task <a href="./../epics/mobile/connector-framework.html#-26--tier-3-connector-scaffolding">2.6</a> (Tier 3 scaffolding) has to land first. Once it does, task 11.1 is smaller in native surface than Calendar and can start independently of it — the two don&#39;t depend on each other, only on 2.6.</p>',20)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
